SELECT h.notification_id,COALESCE(t.type, l.type, st.type) AS usertype,COALESCE(t.name, l.name, st.name) AS userName,h.user_id, h.type,COALESCE(t.phone, l.phone, st.phone) AS phone,h.level,h.time,h.reading_key,h.reading_value,h.recommended_action FROM health_warning_notifications h LEFT JOIN teacher t ON h.user_id = t.teacher_id LEFT JOIN logistics l ON h.user_id = l.logistics_id LEFT JOIN student st ON h.user_id = st.student_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT h.notification_id,h.user_id,st.grade as userGrade,st.name AS userName,st.clazz AS userPost, h.type,st.phone AS phone,h.level,st.sex,h.reading_value,h.recommended_action,h.time FROM health_warning_notifications h LEFT JOIN student st ON h.user_id = st.student_id where st.name like concat('%',#{value},'%') and h.user_id = st.student_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

