SELECT h.notification_id,l.sex,l.clazz as userPost,h.user_id as userId,l.name AS userName,h.type AS type,l.phone AS phone,h.level,h.reading_key,h.reading_value,h.recommended_action,h.time FROM health_warning_notifications h LEFT JOIN student l ON h.user_id = l.student_id
and h.user_id = l.student_id
and h.user_id like concat('%',#{id},'%')
and h.level like concat('%',#{type},'%')
and h.time between #{startTime} and #{endTime}
order by h.time desc limit #{size} offset #{offset}

